return items.map(item => {
  const d = item.json || {};

  const esc = (v) => String(v ?? '')
    .trim()
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "''");

  return {
    json: {
      dni: String(d.dni || '').trim(),
      correo: String(d.correo || '').trim().toLowerCase(),
      nombres_form: String(d.nombres_apellidos || '').trim(),
      programa_form: String(d.programa_academico || '').trim(),
      periodo_academico: String(d.periodo_academico || '').trim(),
      curso: String(d.curso || '').trim(),

      dni_sql: esc(d.dni),
      correo_sql: esc(String(d.correo || '').toLowerCase()),
      nombres_form_sql: esc(d.nombres_apellidos),
      programa_form_sql: esc(d.programa_academico),
      periodo_sql: esc(d.periodo_academico),
      curso_sql: esc(d.curso)
    }
  };
});

return items.map(item => {
  const d = item.json || {};
  const ahora = new Date();
  const ts = Date.now();
  const fecha = ahora.toISOString().slice(0,19).replace('T',' ');

  const encontrado = Number(d.estudiante_encontrado || 0) === 1;

  const codigo = encontrado
    ? String(d.codigo_estudiante_bd || '').trim()
    : 'EST-' + ts;

  const nombre = encontrado
    ? String(d.nombre_estudiante_bd || '').trim()
    : String(d.nombres_form || '').trim();

  const programa = encontrado
    ? String(d.programa_academico_bd || '').trim()
    : String(d.programa_form || '').trim();

  const dni = String(d.dni || '').trim();
  const correo = String(d.correo || '').trim().toLowerCase();
  const periodo = String(d.periodo_academico || '').trim();
  const curso = String(d.curso || '').trim();

  const datosNuevoCompletos = encontrado || Boolean(nombre && programa);
  const completo = Boolean(dni && correo && nombre && programa && periodo && curso && datosNuevoCompletos);

  const esc = (v) => String(v ?? '')
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "''");

  return {
    json: {
      estudiante_encontrado: encontrado,
      estudiante_nuevo: !encontrado,
      registro_valido: completo,

      id_ejecucion: 'MAT-SIN-' + ts + '-' + Math.random().toString(36).slice(2,7),
      id_incidente: 'INC-MAT-' + ts + '-' + Math.random().toString(36).slice(2,7),

      flujo: '03',
      proceso: 'matricula',
      escenario: 'sin_seguridad',
      bloque: 'sin_seguridad',

      codigo_estudiante: codigo,
      dni,
      correo,
      nombre_estudiante: nombre,
      programa_academico: programa,
      periodo_academico: periodo,
      curso,

      estado_matricula: completo ? 'procesada' : 'rechazada',
      estado_ejecucion: completo ? 'success' : 'error',

      categoria_sistema: completo
        ? (encontrado ? 'matricula_estudiante_existente' : 'matricula_estudiante_nuevo')
        : 'registro_incompleto',

      categoria_real: 'pendiente_validacion',
      clasificacion_correcta: false,
      score_riesgo: null,
      nivel: null,

      accion_ejecutada: completo
        ? (encontrado
            ? 'Matrícula procesada para estudiante registrado sin controles SOAR'
            : 'Nuevo estudiante registrado y matrícula procesada sin controles SOAR')
        : 'Matrícula rechazada por datos incompletos',

      hora_ingreso: fecha,
      hora_procesamiento: fecha,

      codigo_sql: esc(codigo),
      dni_sql: esc(dni),
      correo_sql: esc(correo),
      nombre_sql: esc(nombre),
      programa_sql: esc(programa),
      periodo_sql: esc(periodo),
      curso_sql: esc(curso)
    }
  };
});
